std::unique_ptr<FileHandle> open_file(const char* path) {
    // Acquire resource safely (using a factory)
    // If this construction throws, no leakage occurs.
    auto handle = std::make_unique<FileHandle>(path, "r");
    return handle;
} // Resource released automatically on unique_ptr destruction.

void use_file() {
    auto file_ptr = open_file("data.txt");
    // ... potentially throwing operations ...
} // file_ptr goes out of scope; dtor releases FileHandle.
